/**
 * @file tests/dreamstate/verify-fallback-contamination.test.ts
 * @description Jest test for fallback contamination verification
 * @version 6.1.4
 */

import { execSync } from 'child_process';
import * as fs from 'fs';
import * as path from 'path';

describe('Fallback Contamination Verification', () => {
  const testFile = 'tests/dreamstate/fallback-contamination-sandbox.test.ts';
  const logPath = path.join(__dirname, 'fallback-contamination-test-results.log');
  const errorPath = path.join(__dirname, 'fallback-contamination-test-error.log');

  beforeAll(() => {
    // Ensure test file exists
    expect(fs.existsSync(testFile)).toBe(true);
  });

  afterAll(() => {
    // Clean up log files
    if (fs.existsSync(logPath)) {
      fs.unlinkSync(logPath);
    }
    if (fs.existsSync(errorPath)) {
      fs.unlinkSync(errorPath);
    }
  });

  test('should verify fallback contamination sandbox tests are functional', async () => {
    console.log('🔍 Running fallback contamination sandbox tests...');
    
    try {
      // Run the test command
      const result = execSync(`npx jest ${testFile} --no-cache --passWithNoTests`, { 
        encoding: 'utf8',
        stdio: 'pipe',
        timeout: 30000
      });
      
      // Save the output for debugging
      fs.writeFileSync(logPath, result);
      
      // Check if there are failing tests by looking for 'FAIL' in the output
      expect(result).not.toMatch(/FAIL /);
      expect(result).not.toMatch(/× /);
      
      console.log('✅ ALL TESTS PASSED');
      console.log(`Test output saved to: ${logPath}`);
      
    } catch (error: any) {
      // Save error details for debugging
      fs.writeFileSync(errorPath, String(error));
      console.log(`Error details written to: ${errorPath}`);
      
      // Re-throw for Jest to handle
      throw new Error(`Fallback contamination tests failed: ${error.message}`);
    }
  });

  test('should validate fallback contamination test file structure', () => {
    const testContent = fs.readFileSync(testFile, 'utf8');
    
    // Check for essential test patterns
    expect(testContent).toMatch(/describe\(/);
    expect(testContent).toMatch(/test\(|it\(/);
    expect(testContent).toMatch(/fallback/i);
    expect(testContent).toMatch(/contamination/i);
    
    console.log('✅ Test file structure validated');
  });

  test('should confirm emotional sovereignty compliance in fallback tests', () => {
    const testContent = fs.readFileSync(testFile, 'utf8');
    
    // Check for emotional sovereignty patterns
    const emotionalPatterns = [
      /trust.*score/i,
      /emotional/i,
      /fallback/i,
      /contamination/i
    ];
    
    emotionalPatterns.forEach(pattern => {
      expect(testContent).toMatch(pattern);
    });
    
    console.log('✅ Emotional sovereignty compliance confirmed');
  });
}); 